-- R6 S71: the tenant boundary (D174, D178, D179, D185, D186 as amended; spec r6 "SQL contracts"). The tenant of a
-- transaction is the transaction-local setting app.tenant_id, written by the backend at transaction begin with
-- set_config(..., true) (TenantBindingTransactionManager), never at session level. '' or never set = unset: the reader
-- below raises RS003, so a code path without a tenant fails loudly. Every tenant policy is generated by the helpers
-- below and is RESTRICTIVE, so it is ANDed with every permissive store policy, present and future. Policies stay TO
-- PUBLIC and no policy names a role: the owner bypasses RLS, so they bind exactly the application role (D163).

-- 1. The reader. STABLE PARALLEL SAFE (spec); RS003 = tenant not set (distinct from the store scope's RS001).
CREATE FUNCTION shared.rls_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE PARALLEL SAFE AS
$$
DECLARE
    v_tenant text := current_setting('app.tenant_id', true);
BEGIN
    IF v_tenant IS NULL OR v_tenant = '' THEN
        RAISE EXCEPTION USING ERRCODE = 'RS003',
            MESSAGE = format('tenant not set (origin %s)', shared.rls_scope_origin());
    END IF;
    RETURN v_tenant::uuid;
END;
$$;

-- Trigger: a row never moves to another tenant (RS002, like a store change).
CREATE FUNCTION shared.rls_reject_tenant_change() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION USING ERRCODE = 'RS002',
        MESSAGE = format('tenant change refused on %I.%I (origin %s)', TG_TABLE_SCHEMA, TG_TABLE_NAME,
                         shared.rls_scope_origin());
END;
$$;

-- 2. Registries. TENANT: every table the tenant helper protected (the startup check requires its restrictive
-- tenant_scope policy to stay). PLATFORM (D179): no tenant by decision, with its reason. Both written by migrations
-- only; the pool reads them.
CREATE TABLE shared.rls_tenant_table
(
    table_name regclass NOT NULL,
    CONSTRAINT rls_tenant_table_pk PRIMARY KEY (table_name)
);
ALTER TABLE shared.rls_tenant_table ENABLE ROW LEVEL SECURITY;
ALTER TABLE shared.rls_tenant_table FORCE ROW LEVEL SECURITY;
CREATE POLICY registry_read ON shared.rls_tenant_table AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);

CREATE TABLE shared.rls_platform_table
(
    table_name regclass NOT NULL,
    reason     text     NOT NULL,
    CONSTRAINT rls_platform_table_pk PRIMARY KEY (table_name),
    CONSTRAINT rls_platform_table_reason_ck CHECK (btrim(reason) <> '')
);
ALTER TABLE shared.rls_platform_table ENABLE ROW LEVEL SECURITY;
ALTER TABLE shared.rls_platform_table FORCE ROW LEVEL SECURITY;
CREATE POLICY registry_read ON shared.rls_platform_table AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);

CREATE FUNCTION shared.rls_register_platform(p_table regclass, p_reason text) RETURNS void
    LANGUAGE sql AS
$$
DELETE FROM shared.rls_unscoped_table WHERE table_name = p_table;
INSERT INTO shared.rls_platform_table (table_name, reason)
VALUES (p_table, p_reason)
ON CONFLICT (table_name) DO UPDATE SET reason = excluded.reason
$$;

-- 3. The canonical tenant policy (D179). Asserts the D180 recipe was applied first: tenant_id uuid NOT NULL with
-- DEFAULT shared.rls_tenant_id() (an insert takes the bound tenant; unbound raises RS003), and the table's identity
-- includes the tenant: UNIQUE (tenant_id, id) when it has an id (the target of composite foreign keys), otherwise a
-- primary key that leads with tenant_id (shared.idempotency_record). Then ENABLE + FORCE, the restrictive tenant_scope
-- policy, the tenant_fixed trigger, and both registries.
CREATE FUNCTION shared.rls_protect_tenant(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
DECLARE
    v_tenant smallint;
    v_id     smallint;
BEGIN
    SELECT a.attnum
    INTO v_tenant
    FROM pg_catalog.pg_attribute a
             JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
    WHERE a.attrelid = p_table
      AND a.attname = 'tenant_id'
      AND a.atttypid = 'uuid'::regtype
      AND a.attnotnull
      AND NOT a.attisdropped
      AND EXISTS (SELECT 1
                  FROM pg_catalog.pg_depend dep
                  WHERE dep.classid = 'pg_catalog.pg_attrdef'::regclass
                    AND dep.objid = d.oid
                    AND dep.refclassid = 'pg_catalog.pg_proc'::regclass
                    AND dep.refobjid = 'shared.rls_tenant_id()'::regprocedure);
    IF v_tenant IS NULL THEN
        RAISE EXCEPTION '% has no tenant_id uuid NOT NULL DEFAULT shared.rls_tenant_id()', p_table
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT a.attnum
    INTO v_id
    FROM pg_catalog.pg_attribute a
    WHERE a.attrelid = p_table
      AND a.attname = 'id'
      AND NOT a.attisdropped;
    IF v_id IS NOT NULL AND NOT EXISTS (SELECT 1
                                        FROM pg_catalog.pg_index i
                                        WHERE i.indrelid = p_table
                                          AND i.indisunique
                                          AND i.indpred IS NULL
                                          AND i.indnkeyatts = 2
                                          AND i.indkey[0] = v_tenant
                                          AND i.indkey[1] = v_id) THEN
        RAISE EXCEPTION '% has no UNIQUE (tenant_id, id)', p_table USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_id IS NULL AND NOT EXISTS (SELECT 1
                                    FROM pg_catalog.pg_index i
                                    WHERE i.indrelid = p_table
                                      AND i.indisprimary
                                      AND i.indkey[0] = v_tenant) THEN
        RAISE EXCEPTION '% has no id and no primary key leading with tenant_id', p_table
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY tenant_scope ON %s AS RESTRICTIVE FOR ALL TO PUBLIC '
                       || 'USING (tenant_id = (SELECT shared.rls_tenant_id())) '
                       || 'WITH CHECK (tenant_id = (SELECT shared.rls_tenant_id()))', p_table);
    EXECUTE format('CREATE TRIGGER tenant_fixed BEFORE UPDATE OF tenant_id ON %s FOR EACH ROW '
                       || 'WHEN (OLD.tenant_id IS DISTINCT FROM NEW.tenant_id) '
                       || 'EXECUTE FUNCTION shared.rls_reject_tenant_change()', p_table);
    INSERT INTO shared.rls_tenant_table (table_name) VALUES (p_table) ON CONFLICT (table_name) DO NOTHING;
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

-- TENANT class (D179): no store predicate. A restrictive policy alone shows no row, so the permissive tenant_rows
-- (true) makes the tenant's rows visible; the restrictive tenant_scope is ANDed with it.
CREATE FUNCTION shared.rls_protect_tenant_table(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    PERFORM shared.rls_protect_tenant(p_table);
    EXECUTE format('CREATE POLICY tenant_rows ON %s AS PERMISSIVE FOR ALL TO PUBLIC USING (true) WITH CHECK (true)',
                   p_table);
END;
$$;

-- The store helpers call the tenant helper first (spec). A module table gets its tenant_id in the module's own R6
-- slice (S74), while the module migrations of the RLS run, which call these helpers, run after this one on a fresh
-- database: so the tenant helper runs when the table already carries tenant_id, and a table without one keeps the
-- store policy only until its slice adds the column and calls shared.rls_protect_tenant. The per-module
-- assertModuleTenantProtected (RowLevelSecurityCoverageTest) is what refuses a converted module without it.
CREATE FUNCTION shared.rls_protect_tenant_when_present(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    IF EXISTS (SELECT 1
               FROM pg_catalog.pg_attribute a
               WHERE a.attrelid = p_table
                 AND a.attname = 'tenant_id'
                 AND NOT a.attisdropped) THEN
        PERFORM shared.rls_protect_tenant(p_table);
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION shared.rls_protect_store_table(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    PERFORM shared.rls_require_store_column(p_table);
    PERFORM shared.rls_protect_tenant_when_present(p_table);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY store_scope ON %s AS PERMISSIVE FOR ALL TO PUBLIC USING (%s) WITH CHECK (%s)',
                   p_table, shared.rls_visible('store_id'), shared.rls_visible('store_id'));
    EXECUTE format('CREATE TRIGGER store_scope_fixed BEFORE UPDATE OF store_id ON %s FOR EACH ROW '
                       || 'WHEN (OLD.store_id IS DISTINCT FROM NEW.store_id) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_table);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

CREATE OR REPLACE FUNCTION shared.rls_protect_store_or_all_table(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    PERFORM shared.rls_require_store_column(p_table);
    PERFORM shared.rls_protect_tenant_when_present(p_table);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY store_or_all_read ON %s AS PERMISSIVE FOR SELECT TO PUBLIC '
                       || 'USING (store_id IS NULL OR %s)', p_table, shared.rls_visible('store_id'));
    EXECUTE format('CREATE POLICY store_or_all_insert ON %s AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK (%s)',
                   p_table, shared.rls_visible('store_id'));
    EXECUTE format('CREATE POLICY store_or_all_update ON %s AS PERMISSIVE FOR UPDATE TO PUBLIC '
                       || 'USING (store_id IS NULL OR %s) WITH CHECK (%s)', p_table, shared.rls_visible('store_id'),
                   shared.rls_visible('store_id'));
    EXECUTE format('CREATE POLICY store_or_all_delete ON %s AS PERMISSIVE FOR DELETE TO PUBLIC USING (%s)',
                   p_table, shared.rls_visible('store_id'));
    EXECUTE format('CREATE TRIGGER store_scope_fixed BEFORE UPDATE OF store_id ON %s FOR EACH ROW '
                       || 'WHEN (OLD.store_id IS DISTINCT FROM NEW.store_id) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_table);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

CREATE OR REPLACE FUNCTION shared.rls_protect_child_table(p_table regclass, p_fk_column name, p_parent regclass,
                                                          p_parent_key name) RETURNS void
    LANGUAGE plpgsql AS
$$
DECLARE
    v_visible text;
BEGIN
    PERFORM shared.rls_require_store_column(p_parent);
    PERFORM shared.rls_protect_tenant_when_present(p_table);
    v_visible := format('EXISTS (SELECT 1 FROM %s p WHERE p.%I = %s.%I AND %s)', p_parent, p_parent_key, p_table,
                        p_fk_column, shared.rls_visible('p.store_id'));
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY parent_scope ON %s AS PERMISSIVE FOR ALL TO PUBLIC USING (%s) WITH CHECK (%s)',
                   p_table, v_visible, v_visible);
    EXECUTE format('CREATE TRIGGER parent_fixed BEFORE UPDATE OF %I ON %s FOR EACH ROW '
                       || 'WHEN (OLD.%I IS DISTINCT FROM NEW.%I) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_fk_column, p_table, p_fk_column,
                   p_fk_column);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

CREATE OR REPLACE FUNCTION shared.rls_protect_store_or_all_child_table(p_table regclass, p_fk_column name,
                                                                       p_parent regclass,
                                                                       p_parent_key name) RETURNS void
    LANGUAGE plpgsql AS
$$
DECLARE
    v_parent text;
    v_read   text;
    v_write  text;
BEGIN
    PERFORM shared.rls_require_store_column(p_parent);
    PERFORM shared.rls_protect_tenant_when_present(p_table);
    v_parent := format('EXISTS (SELECT 1 FROM %s p WHERE p.%I = %s.%I AND %%s)', p_parent, p_parent_key, p_table,
                       p_fk_column);
    v_read := format(v_parent, '(p.store_id IS NULL OR ' || shared.rls_visible('p.store_id') || ')');
    v_write := format(v_parent, shared.rls_visible('p.store_id'));
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY store_or_all_parent_read ON %s AS PERMISSIVE FOR SELECT TO PUBLIC USING (%s)',
                   p_table, v_read);
    EXECUTE format('CREATE POLICY store_or_all_parent_insert ON %s AS PERMISSIVE FOR INSERT TO PUBLIC '
                       || 'WITH CHECK (%s)', p_table, v_write);
    EXECUTE format('CREATE POLICY store_or_all_parent_update ON %s AS PERMISSIVE FOR UPDATE TO PUBLIC USING (%s) '
                       || 'WITH CHECK (%s)', p_table, v_read, v_write);
    EXECUTE format('CREATE POLICY store_or_all_parent_delete ON %s AS PERMISSIVE FOR DELETE TO PUBLIC USING (%s)',
                   p_table, v_write);
    EXECUTE format('CREATE TRIGGER parent_fixed BEFORE UPDATE OF %I ON %s FOR EACH ROW '
                       || 'WHEN (OLD.%I IS DISTINCT FROM NEW.%I) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_fk_column, p_table, p_fk_column,
                   p_fk_column);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

-- 4. The D42 probe, now tenant-aware (D179): another tenant's row reads as absent (NULL -> 404, existence never
-- revealed), another store of the same tenant still answers its store_id (-> 403). The bound tenant is read first, so
-- an unbound call raises RS003. A table without tenant_id (a module before its S74 slice) has only the bootstrap
-- tenant's rows. EXECUTE is the application role's only (rule 9).
CREATE OR REPLACE FUNCTION shared.store_of(t regclass, id uuid) RETURNS uuid
    LANGUAGE plpgsql
    STABLE
    SECURITY DEFINER
    SET search_path = pg_catalog AS
$$
DECLARE
    v_tenant uuid := shared.rls_tenant_id();
    v_key    name;
    v_store  uuid;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid = t AND c.relrowsecurity) THEN
        RAISE EXCEPTION 'shared.store_of: % has no row-level security', t USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF NOT EXISTS (SELECT 1
                   FROM pg_catalog.pg_attribute a
                   WHERE a.attrelid = t
                     AND a.attname = 'store_id'
                     AND a.atttypid = 'pg_catalog.uuid'::pg_catalog.regtype
                     AND NOT a.attisdropped) THEN
        RAISE EXCEPTION 'shared.store_of: % has no store_id', t USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT a.attname
    INTO v_key
    FROM pg_catalog.pg_index i
             JOIN pg_catalog.pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
    WHERE i.indrelid = t
      AND i.indisprimary
      AND i.indnatts = 1
      AND a.atttypid = 'pg_catalog.uuid'::pg_catalog.regtype;
    IF v_key IS NULL THEN
        RAISE EXCEPTION 'shared.store_of: % has no single-column uuid primary key', t
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF EXISTS (SELECT 1
               FROM pg_catalog.pg_attribute a
               WHERE a.attrelid = t
                 AND a.attname = 'tenant_id'
                 AND NOT a.attisdropped) THEN
        EXECUTE pg_catalog.format('SELECT store_id FROM %s WHERE %I = $1 AND tenant_id = $2', t, v_key)
            INTO v_store USING id, v_tenant;
    ELSE
        EXECUTE pg_catalog.format('SELECT store_id FROM %s WHERE %I = $1', t, v_key) INTO v_store USING id;
    END IF;
    RETURN v_store;
END;
$$;
REVOKE EXECUTE ON FUNCTION shared.store_of(regclass, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION shared.store_of(regclass, uuid) TO restaurantpro_app;

-- 5. Job leases (D185 as amended): one row per (job, tenant); acquiring is a compare-and-set on lease_until, and the
-- holder renews its own live lease. PLATFORM: written by the application role, no tenant policy (a job takes the lease
-- before it binds the tenant). The time is the database's, shared by every backend instance.
CREATE TABLE shared.job_lease
(
    job         text                     NOT NULL,
    tenant_id   uuid                     NOT NULL,
    holder      text                     NOT NULL,
    lease_until timestamp with time zone NOT NULL,
    CONSTRAINT job_lease_pk PRIMARY KEY (job, tenant_id),
    CONSTRAINT job_lease_job_not_blank_ck CHECK (btrim(job) <> ''),
    CONSTRAINT job_lease_holder_not_blank_ck CHECK (btrim(holder) <> '')
);

CREATE FUNCTION shared.try_lease(job text, tenant uuid, holder text, ttl interval) RETURNS boolean
    LANGUAGE plpgsql AS
$$
DECLARE
    v_taken boolean;
BEGIN
    INSERT INTO shared.job_lease AS l (job, tenant_id, holder, lease_until)
    VALUES (try_lease.job, try_lease.tenant, try_lease.holder, clock_timestamp() + try_lease.ttl)
    ON CONFLICT ON CONSTRAINT job_lease_pk DO UPDATE
        SET holder = excluded.holder, lease_until = excluded.lease_until
    WHERE l.lease_until <= clock_timestamp()
       OR l.holder = excluded.holder
    RETURNING true INTO v_taken;
    RETURN coalesce(v_taken, false);
END;
$$;

-- 6. Idempotency records become TENANT (D186): the key is (tenant_id, scope, key), so the same key in two tenants is
-- two records, and a replay never crosses tenants. The D180 recipe: a catalog-only column, then the database default.
ALTER TABLE shared.idempotency_record
    ADD COLUMN tenant_id uuid NOT NULL DEFAULT '00000000-0000-7000-8000-000000000001';
ALTER TABLE shared.idempotency_record
    ALTER COLUMN tenant_id SET DEFAULT shared.rls_tenant_id();
ALTER TABLE shared.idempotency_record
    DROP CONSTRAINT idempotency_record_pk,
    ADD CONSTRAINT idempotency_record_pk PRIMARY KEY (tenant_id, scope, key);
DELETE FROM shared.rls_unscoped_table WHERE table_name = 'shared.idempotency_record'::regclass;
SELECT shared.rls_protect_tenant_table('shared.idempotency_record');

-- 7. PLATFORM tables (D179): Modulith's registry (read at startup and by the D88 recovery across tenants; the
-- serialized event carries its tenantId), the Flyway history, the leases and the registries themselves.
SELECT shared.rls_register_platform('public.event_publication',
                                    'Spring Modulith event registry: read at startup and by the D88 recovery across '
                                        || 'tenants; the serialized event carries its tenantId; never reaches a client');
SELECT shared.rls_register_platform('public.event_publication_archive',
                                    'Spring Modulith event registry archive: as event_publication');
SELECT shared.rls_register_platform('public.flyway_schema_history',
                                    'Flyway migration history: schema metadata, read-only to the pool');
SELECT shared.rls_register_platform('shared.job_lease',
                                    'Job leases per (job, tenant) (D185): taken before the tenant is bound');
SELECT shared.rls_register_platform('shared.rls_unscoped_table',
                                    'A row-level security registry: read-only to the pool through its read policy');
SELECT shared.rls_register_platform('shared.rls_protected_table',
                                    'A row-level security registry: read-only to the pool through its read policy');
SELECT shared.rls_register_platform('shared.rls_tenant_table',
                                    'A row-level security registry: read-only to the pool through its read policy');
SELECT shared.rls_register_platform('shared.rls_platform_table',
                                    'A row-level security registry: read-only to the pool through its read policy');
